contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint minSum, uint deposit, uint amount) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        require(minSum > 0);
        require(deposit < minSum);
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Deposit{value: deposit}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethBefore = address(c).balance;
        c.Collect(amount); if (__ESBMC_reverted()) return;
        assert(c.balances(address(this)) == balBefore && address(c).balance == ethBefore);
    }
    receive() external payable {}
}

